1578	function workFindings(rule, work) {
1579	  const s = rule.spec;
1580	  const out = [];
1581	  for (const a of s.checkBranchCommits ?? []) {
1582	    if (a.unlessOnDefaultBranch && work.onDefaultBranch()) continue;
1583	    if (!work.commits.length || work.commits.some((m) => a.someMessageMatches.test(m))) continue;
1584	    const vars = { commits: work.commits.length, base: work.baseRef };
1585	    out.push(finding(rule, { file: '(branch)', what: fill(a.what, vars), fix: fill(a.fix, vars) }));
1586	  }
1587	  const merges = s.forbidIntroducedMergeCommits;
1588	  for (const { sha, subject } of merges ? work.introducedMerges() : []) {
1589	    const vars = { sha, subject };
1590	    out.push(finding(rule, {
1591	      file: `${work.branch || 'HEAD'}@${sha}`, what: fill(merges.what, vars), fix: fill(merges.fix, vars),
1592	    }));
1593	  }
1594	  for (const a of s.forbidAddedValueInArray ?? []) {
1595	    const paths = a.file !== undefined ? [a.file]
1596	      : work.tracked.filter((f) => a.filesMatching.test(f) &&
1597	          (!a.whereFileContains || a.whereFileContains.test(work.read(f) ?? '')));
1598	    for (const path of paths) {
1599	      const { head, base } = work.jsonPair(path);
1600	      if (head == null) continue;
1601	      const valuesAt = (doc) => a.atFields.flatMap((field) => {
1602	        const values = doc == null ? undefined : fieldAt(doc, field);
1603	        return Array.isArray(values) ? values.map(String) : [];
1604	      });
1605	      const before = new Set(valuesAt(base));
1606	      for (const value of new Set(valuesAt(head))) {
1607	        if (before.has(value)) continue;
1608	        const vars = { value };
1609	        out.push(finding(rule, { file: path, what: fill(a.what, vars), fix: fill(a.fix, vars) }));
1610	      }
1611	    }
1612	  }
1613	  const inScope = (a) => work.changedFiles.filter((f) => a.inFilesMatching.test(f) && !excluded(f, s.excludeMatchers));
1614	  for (const a of s.forbidAddedLinesMatching ?? []) {
1615	    for (const { file, line, text } of work.addedLines(inScope(a))) {
1616	      const m = text.match(a.match);
1617	      if (!m || a.unlessLineMatches?.test(text)) continue;
1618	      const vars = { ...(m.groups ?? {}), match: m[0], path: file, line };
1619	      out.push(finding(rule, { file, line, what: fill(a.what, vars), fix: fill(a.fix, vars) }));
1620	    }
1621	  }
1622	  for (const a of s.forbidRemovedLinesMatching ?? []) {
1623	    for (const { file, line, text } of work.removedLines(inScope(a))) {
1624	      const m = text.match(a.match);
1625	      if (!m || a.unlessLineMatches?.test(text)) continue;
1626	      if (a.unlessMatchRemainsInFile && (work.read(file) ?? '').includes(m[0])) continue;
1627	      const vars = { ...(m.groups ?? {}), match: m[0], path: file, line };
1628	      out.push(finding(rule, { file, line, what: fill(a.what, vars), fix: fill(a.fix, vars) }));
1629	    }
1630	  }
1631	  for (const a of s.requireCoChange ?? []) {
1632	    if (work.changedFiles.some((f) => a.requireChangedFileMatching.test(f))) continue;
1633	    const triggering = a.whenChangedFileMatches
1634	      ? work.changedFiles.filter((f) => a.whenChangedFileMatches.test(f))
1635	      : [...new Set(work.addedLines(work.changedFiles.filter((f) => a.whenAddedLineMatches.inFilesMatching.test(f)))
1636	        .filter(({ text }) => a.whenAddedLineMatches.match.test(text))
1637	        .map(({ file }) => file))];
1638	    for (const file of triggering) {
1639	      const vars = { path: file };
1640	      out.push(finding(rule, { file, what: fill(a.what, vars), fix: fill(a.fix, vars) }));
1641	    }
1642	  }
